"""Builds the auto-generated metrics block of docs/EVALS.md from data/evals/results/*.json.

The narrative sections of EVALS.md are hand-written; only the text between
<!-- AUTO:BEGIN --> and <!-- AUTO:END --> is replaced.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path
from typing import Any, Optional

sys.path.insert(0, str(Path(__file__).parent))
from common import EVAL_DATA, ROOT, load_result  # noqa: E402

DOC = ROOT / "docs" / "EVALS.md"
TAGS = ("before", "after")


def g(d: Optional[dict], *path: Any) -> Any:
    for p in path:
        if d is None:
            return None
        d = d.get(p) if isinstance(d, dict) else (d[p] if isinstance(d, list) and isinstance(p, int) and p < len(d) else None)
    return d


def f(v: Any, pct: bool = False) -> str:
    if v is None or (isinstance(v, (dict, list, str)) and not v):
        return "—"
    if isinstance(v, bool):
        return "yes" if v else "no"
    if isinstance(v, float):
        return f"{v * 100:.0f}%" if pct else f"{v:g}"
    if isinstance(v, (list, tuple)) and len(v) == 2 and all(isinstance(x, (int, float)) for x in v):
        return f"[{v[0] * 100:.0f}–{v[1] * 100:.0f}%]" if pct else f"{v[0]}/{v[1]}"
    return str(v)


def e2e_summary(app: str, tag: str) -> dict:
    base = EVAL_DATA / app / tag
    out: dict[str, Any] = {}
    a = base / "A" / "summary.json"
    if a.exists():
        s = json.loads(a.read_text())
        msgs = [json.loads(x) for x in (base / "A" / "messages.jsonl").read_text().splitlines()]
        out["asks"] = len([m for m in msgs if m.get("dir") == "s2c" and m.get("type") == "ask"
                           and m.get("unknown_id") != "phase-debrief"])
        out["events"] = sum(len(m.get("items", [])) for m in msgs if m.get("dir") == "s2c" and m.get("type") == "events")
        kinds: dict[str, int] = {}
        for m in msgs:
            if m.get("dir") == "s2c" and m.get("type") == "events":
                for it in m.get("items", []):
                    kinds[it["kind"]] = kinds.get(it["kind"], 0) + 1
        out["event_kinds"] = kinds
        out["duration_s"] = s.get("duration_s")
        logs = [json.loads(x) for x in (base / "A" / "server_log.jsonl").read_text().splitlines()]
        apps = sorted({e["payload"].get("app") for e in logs if e["kind"] == "screen.state" and e["payload"].get("app")})
        out["app_names_seen"] = apps
    st = base / "state.json"
    if st.exists():
        out["map_build_s"] = json.loads(st.read_text()).get("map_build_s")
    wm = base / "workmap.json" if (base / "workmap.json").exists() else base / "B" / "workmap.json"
    if wm.exists():
        w = json.loads(wm.read_text())
        out["steps"] = len(w.get("steps", []))
        out["guardrails"] = len(w.get("guardrails", []))
        out["predicates"] = sum(1 for x in w.get("guardrails", []) if x.get("predicate"))
        out["map_apps"] = w.get("apps")
        out["coverage"] = g(w, "coverage", "status")
    for ph in ("C", "RU"):
        p = base / ph / "summary.json"
        if p.exists():
            s = json.loads(p.read_text())
            out[f"lookup_{ph}"] = g(s, "lookup", "match", "score")
            if "cases" in s:
                out[f"cases_{ph}"] = [(c["should_intervene"], len(c["interventions"])) for c in s["cases"]]
            else:
                out[f"cases_{ph}"] = [(True, len(s.get("intervene_7200") or [])), (False, len(s.get("intervene_6100") or []))]
    return out


def row(name: str, key: Any, note: str = "", pct: bool = False) -> str:
    vals = [f(key(t), pct) for t in TAGS]
    return f"| {name} | {vals[0]} | {vals[1]} | {note} |"


def write() -> str:
    R = {t: {k: load_result(k, t) for k in ("perception", "tutor_erpnext", "tutor_zammad", "questions", "map",
                                            "predicates_erpnext", "predicates_zammad", "safety")} for t in TAGS}
    E = {t: {app: e2e_summary(app, t) for app in ("erpnext", "zammad")} for t in TAGS}
    voice = load_result("voice", "manual") or load_result("voice")
    L = ["<!-- AUTO:BEGIN (generated by infra/evals/report.py — do not edit by hand) -->", "",
         "| Metric | Before | After | n / note |", "|---|---|---|---|"]
    P = lambda t: R[t]["perception"]  # noqa: E731
    L.append("| **1. Perception (golden keyframes, REST oracle)** | | | |")
    for grp, label in (("ERPNext", "ERPNext"), ("Zammad", "Zammad")):
        L.append(row(f"{label}: view accuracy", lambda t: g(P(t), "final", grp, "view"), f"n={g(P('before'), 'final', grp, 'n')} frames", True))
        L.append(row(f"{label}: entity-id accuracy", lambda t: g(P(t), "final", grp, "entity"), "record frames", True))
        L.append(row(f"{label}: status accuracy", lambda t: g(P(t), "final", grp, "status"), "", True))
        L.append(row(f"{label}: app-name accuracy (single frame)", lambda t: g(P(t), "final", grp, "app"), "", True))
        L.append(row(f"{label}: field value exact match", lambda t: g(P(t), "final", grp, "field_exact"),
                     f"{g(P('before'), 'final', grp, 'n_fields')} fields; lenient "
                     f"{f(g(P('before'), 'final', grp, 'field_lenient'), True)}→{f(g(P('after'), 'final', grp, 'field_lenient'), True)}", True))
    for grp in ("ERPNext/dark", "ERPNext/de", "ERPNext/ru", "ERPNext/z125", "ERPNext/z80", "Zammad/dark", "Zammad/de",
                "Zammad/ru", "Zammad/z125"):
        L.append(row(f"{grp}: view / entity / field-exact",
                     lambda t, grp=grp: None if not P(t) else
                     f"{f(g(P(t), 'final', grp, 'view'), True)} / {f(g(P(t), 'final', grp, 'entity'), True)} / "
                     f"{f(g(P(t), 'final', grp, 'field_exact'), True)}", f"n={g(P('before'), 'final', grp, 'n')}"))
    EV = lambda t: load_result("events", t)  # noqa: E731
    for app in ("erpnext", "zammad"):
        L.append(row(f"{app}: event precision / recall (live capture)", lambda t, app=app: EV(t) and g(EV(t), app) and
                     f"{f(g(EV(t), app, 'precision'), True)} / {f(g(EV(t), app, 'recall'), True)}",
                     f"{g(EV('before'), app, 'n_truth')} scripted actions"))
    L.append(row("Heuristic-only (pre-vision) field exact", lambda t: g(P(t), "heuristic", "all", "field_exact"), "OCR path, no LLM", True))
    L.append(row("OCR CER on amounts", lambda t: g(P(t), "final", "all", "num_cer"), f"n={g(P('before'), 'final', 'all', 'n_numbers')}"))
    L.append(row("OCR+redaction latency p50 / p95 (ms)", lambda t: None if not P(t) else
                 f"{g(P(t), 'latency', 'ocr_redact_ms', 'p50')} / {g(P(t), 'latency', 'ocr_redact_ms', 'p95')}", "M-series CPU"))
    L.append(row("Vision LLM latency p50 / p95 (ms)", lambda t: None if not P(t) else
                 f"{g(P(t), 'latency', 'vision_ms', 'p50')} / {g(P(t), 'latency', 'vision_ms', 'p95')}", "GLM-5.3-Flash"))
    L.append(row("Keyframe → final state p50 / p95 (ms)", lambda t: None if not P(t) else
                 f"{g(P(t), 'latency', 'final_state_ms', 'p50')} / {g(P(t), 'latency', 'final_state_ms', 'p95')}", ""))

    L.append("| **2. Generalization: Zammad capture → map → learn** | | | |")
    Z = lambda t: E[t]["zammad"]  # noqa: E731
    L.append(row("Capture: asks / duration", lambda t: Z(t) and f"{Z(t).get('asks')} / {Z(t).get('duration_s')} s", "3 tickets"))
    L.append(row("Capture: screen events (kinds)", lambda t: Z(t) and f"{Z(t).get('events')} {Z(t).get('event_kinds')}", "edits of group/priority, Update = save expected"))
    L.append(row("Distinct app names in one session", lambda t: Z(t) and Z(t).get("app_names_seen"), "should be 1"))
    L.append(row("Map: steps / guardrails / deterministic predicates", lambda t: Z(t) and
                 f"{Z(t).get('steps')} / {Z(t).get('guardrails')} / {Z(t).get('predicates')}", f"map apps {Z('before').get('map_apps')}"))
    L.append(row("Map build (s)", lambda t: Z(t).get("map_build_s"), ""))
    L.append(row("Learner EN (should, got interventions)", lambda t: Z(t).get("cases_C"), "75 EUR / 30 EUR"))
    L.append(row("Learner RU (should, got interventions)", lambda t: Z(t).get("cases_RU"), "120 EUR / 25 EUR"))
    L.append(row("Lookup score EN / RU", lambda t: Z(t) and f"{f(Z(t).get('lookup_C'))} / {f(Z(t).get('lookup_RU'))}", ""))
    L.append(row("ERPNext replay (scripted A–RU): asks / events", lambda t: E[t]["erpnext"] and
                 f"{E[t]['erpnext'].get('asks')} / {E[t]['erpnext'].get('events')}", "same harness as E2E_REPORT"))
    L.append(row("ERPNext 7,200 / 6,100 (should, got)", lambda t: E[t]["erpnext"].get("cases_C"), ""))

    L.append("| **3. Tutor guardrails on property-based variants (real screens)** | | | |")
    for app in ("erpnext", "zammad"):
        T = lambda t, app=app: g(R[t][f"tutor_{app}"], "summary")  # noqa: E731
        L.append(row(f"{app}: catch recall (95% CI)", lambda t, T=T: T(t) and
                     f"{f(g(T(t), 'all', 'catch_recall'), True)} {f(g(T(t), 'all', 'catch_recall_ci95'), True)}",
                     f"{g(T('before'), 'all', 'n_pos')} violating cases"))
        L.append(row(f"{app}: false-alarm rate (95% CI)", lambda t, T=T: T(t) and
                     f"{f(g(T(t), 'all', 'false_alarm_rate'), True)} {f(g(T(t), 'all', 'false_alarm_ci95'), True)}",
                     f"{g(T('before'), 'all', 'n_neg')} clean cases"))
        L.append(row(f"{app}: right rule cited (of caught)", lambda t, T=T: g(T(t), "all", "right_rule_rate"), "", True))
        L.append(row(f"{app}: interventions per caught case", lambda t, T=T: g(T(t), "all", "interventions_per_caught_case"), "1 = no repeats"))
        L.append(row(f"{app}: latency open→intervene p50 / p95 (s)", lambda t, T=T: T(t) and
                     f"{g(T(t), 'all', 'latency_p50_s')} / {g(T(t), 'all', 'latency_p95_s')}", ""))
        L.append(row(f"{app}: RU subset recall / FA", lambda t, T=T: T(t) and
                     f"{f(g(T(t), 'ru', 'catch_recall'), True)} / {f(g(T(t), 'ru', 'false_alarm_rate'), True)}",
                     f"n={g(T('before'), 'ru', 'n')}"))
    for app, fams in (("erpnext", None), ("zammad", None)):
        T = lambda t, app=app: g(R[t][f"tutor_{app}"], "summary", "by_family")  # noqa: E731
        for fam in (T("before") or {}):
            L.append(row(f"{app} · {fam}: recall / FA", lambda t, fam=fam, T=T: T(t) and fam in T(t) and
                         f"{f(g(T(t), fam, 'catch_recall'), True)} / {f(g(T(t), fam, 'false_alarm_rate'), True)}",
                         f"n={g(T('before'), fam, 'n')}"))

    L.append("| **4. Questioning** | | | |")
    Q = lambda t: R[t]["questions"]  # noqa: E731
    for i, app in enumerate(("erpnext", "zammad")):
        run = lambda t, app=app: next((r for r in (g(Q(t), "runs") or []) if r["run"].startswith(app)), None)  # noqa: E731
        L.append(row(f"{app} capture: asks / 10 min", lambda t, run=run: g(run(t), "asks_per_10min"), "budget ≤3–5"))
        L.append(row(f"{app}: guardrail-question share (hand / judge)", lambda t, run=run: run(t) and
                     f"{f(run(t)['guardrail_share_hand'], True)} / {f(run(t)['guardrail_share_judge'], True)}", ""))
        L.append(row(f"{app}: answerable-from-screen (hand / judge)", lambda t, run=run: run(t) and
                     f"{f(run(t)['answerable_from_screen_hand'], True)} / {f(run(t)['answerable_from_screen_judge'], True)}", "lower is better"))
        L.append(row(f"{app}: duplicate-question rate (hand / judge)", lambda t, run=run: run(t) and
                     f"{f(run(t)['duplicate_rate_hand'], True)} / {f(run(t)['duplicate_rate_judge'], True)}", ""))
        L.append(row(f"{app}: seeded tacit rules asked about (hand)", lambda t, run=run: g(run(t), "seeded_rule_recall_hand"), "3 seeded"))
    L.append(row("Scope router accuracy, 40 clean unknowns (vs hand)", lambda t: g(Q(t), "scope", "accuracy_vs_hand"), "8 per scope", True))
    L.append(row("Scope router accuracy, 15 cue-free unknowns (vs hand)", lambda t: g(Q(t), "scope_hard", "accuracy_vs_hand"), "", True))
    L.append(row("Expert-vs-not routing accuracy (clean / cue-free)", lambda t: Q(t) and
                 f"{f(g(Q(t), 'scope', 'ask_routing_accuracy'), True)} / {f(g(Q(t), 'scope_hard', 'ask_routing_accuracy'), True)}", ""))
    L.append(row("Hand-vs-judge agreement (Cohen's κ)", lambda t: g(Q(t), "scope", "hand_vs_judge_kappa"), f"judge {g(Q('before'), 'judge')}"))

    L.append("| **5. Map quality** | | | |")
    M = lambda t: R[t]["map"]  # noqa: E731
    for app in ("erpnext", "zammad"):
        L.append(row(f"{app}: step recall / precision (judge)", lambda t, app=app: M(t) and g(M(t), app) and
                     f"{f(g(M(t), app, 'step_recall'), True)} / {f(g(M(t), app, 'step_precision'), True)}",
                     "judge is lenient — see hand alignment below"))
        L.append(row(f"{app}: rules with a deterministic predicate", lambda t, app=app: g(M(t), app, "rules_with_predicate"), ""))
        PR = lambda t, app=app: g(R[t][f"predicates_{app}"], "per_guardrail")  # noqa: E731
        L.append(row(f"{app}: predicate accuracy on oracle vars (per guardrail)", lambda t, PR=PR: PR(t) and
                     "; ".join(f"{k}:{v['rule']} {f(v['accuracy'], True) if v['accuracy'] is not None else 'fuzzy'}"
                               for k, v in PR(t).items()), "no perception in the loop"))

    L.append("| **6. Adversarial / safety** | | | |")
    S = lambda t: R[t]["safety"]  # noqa: E731
    L.append(row("PII redaction recall", lambda t: S(t) and g(S(t), "pii", "recall") is not None and
                 f"{f(g(S(t), 'pii', 'recall'), True)} ({g(S(t), 'pii', 'n_pii')} values)", "EN/DE/RU forms + prose + real Zammad ticket"))
    L.append(row("PII over-redaction of non-PII controls", lambda t: g(S(t), "pii", "over_redaction_rate"), "", True))
    L.append(row("Off-record leaks (stores containing secrets)", lambda t: g(S(t), "offrecord", "n_leaks"), "0 required"))
    L.append(row("Prompt injection complied (any surface)", lambda t: g(S(t), "injection", "complied_any"), "learner ERPNext + Zammad, capture → map"))
    L.append(row("Injection: map gained a rule the expert never said", lambda t: g(S(t), "injection", "capture_map", "map_non_expert_rule_from_screen_text"), "defensive, but not expert-sourced"))
    L.append(row("Injection: guardrail still fired on injected 7,200 invoice", lambda t: S(t) and bool(g(S(t), "injection", "erp_learner", "intervened")), ""))
    L.append(row("Contradictory expert answer flagged", lambda t: g(S(t), "expert", "contradiction_flagged_in_dialog"), "debrief on a map copy"))
    L.append(row("“I don't know” turned into a rule", lambda t: g(S(t), "expert", "idk_became_rule"), ""))
    L.append(row("Invented rules (judge) ERPNext / Zammad", lambda t: S(t) and g(S(t), "invent") and
                 f"{g(S(t), 'invent', 'erpnext', 'invented_judge')}/{g(S(t), 'invent', 'erpnext', 'n')} · "
                 f"{g(S(t), 'invent', 'zammad', 'invented_judge')}/{g(S(t), 'invent', 'zammad', 'n')}", "learner baiting"))
    L.append(row("Bait answered with yes/right (regex)", lambda t: S(t) and g(S(t), "invent") and
                 f"{g(S(t), 'invent', 'erpnext', 'affirmed')} · {g(S(t), 'invent', 'zammad', 'affirmed')}", ""))

    L.append("| **7. Voice loop** | | | |")
    hv = g(voice, "headless_custom_llm_ttft") or {}
    L.append(f"| Custom-LLM TTFT, headless (user turns) p50 / p95 ms | {g(hv, 'user', 'p50_ms')} / {g(hv, 'user', 'p95_ms')} | | "
             f"n={g(hv, 'user', 'n')}, all runs; no audio |")
    L.append(f"| ElevenLabs per-turn metrics | {('n/a — ' + voice['note']) if voice and voice.get('note') else json.dumps(g(voice, 'elevenlabs_turn_metrics_ms'))} | | "
             f"`voice_metrics.py` after a real call |")
    L += ["", "<!-- AUTO:END -->"]
    block = "\n".join(L)
    if DOC.exists():
        txt = DOC.read_text()
        if "<!-- AUTO:BEGIN" in txt:
            txt = re.sub(r"<!-- AUTO:BEGIN.*?<!-- AUTO:END -->", lambda _: block, txt, flags=re.S)
        else:
            txt += "\n\n" + block + "\n"
    else:
        txt = "# Claros evals\n\n" + block + "\n"
    DOC.write_text(txt)
    print(block)
    return block


if __name__ == "__main__":
    write()
